import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import { randomUUID } from 'crypto';

const s3 = new S3Client({ region: '{{region}}' });

export async function createUploadUrl(filename: string, contentType: string) {
  const key = `{{key_prefix}}/${Date.now()}-${randomUUID()}-${filename}`;
  const cmd = new PutObjectCommand({
    Bucket: '{{bucket_name}}',
    Key: key,
    ContentType: contentType,
  });
  const url = await getSignedUrl(s3, cmd, { expiresIn: {{expires_seconds}} });
  return { url, key, method: 'PUT', headers: { 'Content-Type': contentType } };
}
